## Code Example
```javascript
function minCostPartitions(A, k) {
  const n = A.length;
  const dp = Array.from({ length: n + 1 }, () => Array(k + 1).fill(Infinity));
  const pre = Array.from({ length: n + 1 }, () => Array(k + 1).fill(-1));

  dp[0][0] = 0;

  // Base case: single segment
  for (let i = 1; i <= n; i++) {
    let maxVal = A[0], minVal = A[0];
    for (let j = 0; j < i; j++) {
      maxVal = Math.max(maxVal, A[j]);
      minVal = Math.min(minVal, A[j]);
      dp[i][1] = maxVal - minVal;
    }
  }

  // DP transitions
  for (let t = 2; t <= k; t++) {
    for (let i = 1; i <= n; i++) {
      for (let j = t - 1; j < i; j++) {
        const segmentCost = computeCost(A, j + 1, i);
        if (dp[j][t - 1] + segmentCost < dp[i][t]) {
          dp[i][t] = dp[j][t - 1] + segmentCost;
          pre[i][t] = j;
        }
      }
    }
  }

  // Reconstruct segments
  const segments = [];
  let end = n;
  for (let t = k; t >= 1; t--) {
    const start = pre[end][t] + 1;
    segments.unshift([start, end]);
    end = pre[end][t];
  }

  return { minCost: dp[n][k], segments };
}
```

## Why This Is Asked
Tests interval DP with exactly k block selection, reconstruction, and non-adjacent constraint handling. Requires precomputing interval values (max-min) and a clean end-at-i transition that accounts for the gap requirement.

## Key Concepts
- Interval DP with exactly k non-adjacent blocks
- Precomputation of val(l,r) = max(A[l..r]) - min(A[l..r]) using O(n²) sliding window enumeration
- Reconstruction pointers to retrieve endpoints
- Time complexity: O(n²) precomputation + O(kn²) DP; Space: O(n²) for val table + O(n·k) for DP
- Edge cases: k > ⌊n/2⌋ (impossible, return error), empty arrays (return 0)

## Code Example
```javascript
function maxKSumIntervals(A, k) {
  const n = A.length;
  const val = Array.from({ length: n }, () => Array(n).fill(0));

  for (let l = 0; l < n; l++) {
    let min = A[l], max = A[l];
    for (let r = l; r < n; r++) {
      min = Math.min(min, A[r]);
      max = Math.max(max, A[r]);
      val[l][r] = max - min;
    }
  }

  const dp = Array.from({ length: n + 1 }, () => Array(k + 1).fill(-Infinity));
  const parent = Array.from({ length: n + 1 }, () => Array(k + 1).fill(null));

  for (let i = 0; i <= n; i++) dp[i][0] = 0;

  for (let i = 1; i <= n; i++) {
    for (let t = 1; t <= k; t++) {
      dp[i][t] = dp[i-1][t];
      parent[i][t] = { skip: true };

      for (let j = 1; j <= i; j++) {
        const prev = j >= 2 ? dp[j-2][t-1] : (t === 1 ? 0 : -Infinity);
        if (prev === -Infinity) continue;
        const curr = prev + val[j-1][i-1];
        if (curr > dp[i][t]) {
          dp[i][t] = curr;
          parent[i][t] = { start: j, end: i, prev: j - 2 };
        }
      }
    }
  }

  const intervals = [];
  let i = n, t = k;
  while (t > 0 && parent[i][t]) {
    const p = parent[i][t];
    if (!p.skip) {
      intervals.push([p.start, p.end]);
      i = p.prev;
      t--;
    } else {
      i--;
    }
  }

  return { maxValue: dp[n][k], intervals: intervals.reverse() };
}
```

